/// One icon at the text's size and color, hidden from screen readers since
/// the label beside it says the same.
pub fn icon(inner: &'static str) -> impl IntoView {
    view! {
        <svg class="h-4 w-4 shrink-0" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"
            stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"
            aria-hidden="true" inner_html=inner></svg>
    }
}
